let CURRENT_LANG = (function(){
  try {
    const cached = localStorage.getItem('aap_lang');
    if (cached === 'zh' || cached === 'en') return cached;
  } catch {}
  // default to Chinese; only switch to English when user explicitly toggles
  return 'zh';
})();
function t(key) {
  const pack = I18N[CURRENT_LANG] || I18N.zh;
  return (key in pack) ? pack[key] : (I18N.zh[key] ?? key);
}
function applyI18n() {
  document.documentElement.lang = CURRENT_LANG === 'zh' ? 'zh-CN' : 'en';
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.getAttribute('data-i18n')); });
  document.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t(el.getAttribute('data-i18n-html')); });
  document.querySelectorAll('[data-i18n-placeholder]').forEach(el => { el.placeholder = t(el.getAttribute('data-i18n-placeholder')); });
  document.querySelectorAll('[data-i18n-title]').forEach(el => { el.title = t(el.getAttribute('data-i18n-title')); });
  const tog = document.getElementById('btnLangToggle');
  if (tog) tog.textContent = t('lang_toggle');
}
function setLang(lang) {
  if (lang !== 'zh' && lang !== 'en') return;
  CURRENT_LANG = lang;
  try { localStorage.setItem('aap_lang', lang); } catch {}
  applyI18n();
  // Re-render dynamic views that emit translated text.
  try { renderUserbar(); } catch {}
  try { if (gameId && state) render(); } catch {}
  try { if (!gameId) loadRooms(); } catch {}
  try { if (typeof _refreshChatInputState === 'function') _refreshChatInputState(); } catch {}
  try { if (currentUser && document.querySelector('.modal-bg.open[data-mod=\"account\"]')) refreshAccount(); } catch {}
  try { if (currentUser && currentUser.is_admin && document.querySelector('.modal-bg.open[data-mod=\"admin\"]')) refreshAdmin(); } catch {}
}
